BEGIN;
SELECT no_plan();
INSERT INTO public.chart_of_accounts(id,tenant_id,account_code,name_ar,name_en,account_type,normal_balance) VALUES
('84000000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000001','8401','Bank fixture','Bank fixture','asset','debit'),
('84000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000002','8402','Other fixture','Other fixture','asset','debit');
CREATE TEMP TABLE bank_fixture(input jsonb,result jsonb);
INSERT INTO bank_fixture(input) VALUES ('{"bank_name":"Fixture Bank","account_name":"Operating","iban":"sa60 8401 0000 0000 0000 0001","currency":"SAR","opening_balance":10.25,"coa_account_code":"8401"}');
GRANT ALL ON bank_fixture TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
UPDATE bank_fixture SET result=public.save_bank_account(input);
SELECT is((SELECT iban FROM public.bank_accounts WHERE id=(SELECT (result->>'id')::uuid FROM bank_fixture)),'SA6084010000000000000001','IBAN normalized');
SELECT is((SELECT opening_balance FROM public.bank_accounts WHERE id=(SELECT (result->>'id')::uuid FROM bank_fixture)),10.25::numeric,'opening amount preserved exactly');
SELECT throws_ok($$SELECT public.save_bank_account(input) FROM bank_fixture$$,'P0001','BNK004: bank account IBAN already exists','duplicate IBAN rejected');
SELECT throws_ok($$SELECT public.save_bank_account(input || '{"iban":"SA6084010000000000000002"}') FROM bank_fixture$$,'P0001','BNK001: invalid bank account details','bad checksum rejected');
SELECT throws_ok($$SELECT public.save_bank_account(input || '{"opening_balance":1.005}') FROM bank_fixture$$,'P0001','BNK001: invalid bank account details','excess money precision rejected');
SELECT throws_ok($$SELECT public.save_bank_account(input || '{"coa_account_code":"8402"}') FROM bank_fixture$$,'P0001','BNK005: active tenant asset account required','cross-tenant ledger mapping rejected');
SELECT throws_ok($$SELECT public.save_bank_account(input,(result->>'id')::uuid,'2000-01-01') FROM bank_fixture$$,'P0001','BNK002: bank account changed; reload first','stale update rejected');
SELECT throws_ok($$UPDATE public.bank_accounts SET opening_balance=0 WHERE id=(SELECT (result->>'id')::uuid FROM bank_fixture)$$,'42501',NULL,'direct updates cannot bypass lifecycle/audit');
SELECT lives_ok($$UPDATE bank_fixture SET result=public.save_bank_account(input || '{"account_name":"Updated"}',(result->>'id')::uuid,(result->>'updated_at')::timestamptz)$$,'unused account can be edited');
SELECT is((SELECT account_name FROM public.bank_accounts WHERE id=(SELECT (result->>'id')::uuid FROM bank_fixture)),'Updated','updated name persisted');
SELECT lives_ok($$SELECT public.change_bank_account_state((result->>'id')::uuid,(result->>'updated_at')::timestamptz,'deactivate') FROM bank_fixture$$,'account can be deactivated');
RESET ROLE;
SELECT throws_ok($$INSERT INTO public.bank_transactions(tenant_id,bank_account_id,transaction_date,amount) SELECT '00000000-0000-0000-0000-000000000001',(result->>'id')::uuid,current_date,1 FROM bank_fixture$$,'P0001','BNK005: active tenant bank account required','inactive account blocks new transactions even for service writes');
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.change_bank_account_state((result->>'id')::uuid,(result->>'updated_at')::timestamptz,'activate') FROM bank_fixture$$,'account can be reactivated');
RESET ROLE;
SELECT throws_ok($$INSERT INTO public.bank_transactions(tenant_id,bank_account_id,transaction_date,amount) SELECT '00000000-0000-0000-0000-000000000002',(result->>'id')::uuid,current_date,1 FROM bank_fixture$$,'P0001','BNK005: active tenant bank account required','cross-tenant reference blocked');
INSERT INTO public.bank_transactions(tenant_id,bank_account_id,transaction_date,amount) SELECT '00000000-0000-0000-0000-000000000001',(result->>'id')::uuid,current_date,1 FROM bank_fixture;
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.save_bank_account(input || '{"opening_balance":20}',(result->>'id')::uuid,(result->>'updated_at')::timestamptz) FROM bank_fixture$$,'P0001','BNK003: bank account has financial history; only names and active status may change','financial history freezes opening balance');
SELECT throws_ok($$SELECT public.change_bank_account_state((result->>'id')::uuid,(result->>'updated_at')::timestamptz,'delete') FROM bank_fixture$$,'P0001','BNK003: bank account has financial history; deactivate it instead','used account cannot be deleted');
SELECT lives_ok($$UPDATE bank_fixture SET result=public.save_bank_account(input || '{"account_name":"History retained"}',(result->>'id')::uuid,(result->>'updated_at')::timestamptz)$$,'used account can be renamed');
RESET ROLE;
CREATE FUNCTION pg_temp.fail_bank_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='bank_account_updated' THEN RAISE EXCEPTION 'audit fault'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER trg_bank_test_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_bank_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.save_bank_account(input,(result->>'id')::uuid,(result->>'updated_at')::timestamptz) FROM bank_fixture$$,'P0001','audit fault','audit error rolls back update');
SELECT is((SELECT account_name FROM public.bank_accounts WHERE id=(SELECT (result->>'id')::uuid FROM bank_fixture)),'History retained','failed edit preserved name');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000002","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.change_bank_account_state((result->>'id')::uuid,(result->>'updated_at')::timestamptz,'deactivate') FROM bank_fixture$$,'P0001','PMT006: bank account not found','other tenant cannot deactivate account');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.save_bank_account(input) FROM bank_fixture$$,'P0001','AUTH007: accounting permission required','owner MFA required');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-0000-0000-000000000001","aal":"aal2"}',true);
UPDATE bank_fixture SET result=public.save_bank_account(input || '{"iban":"GB82WEST12345698765432","currency":"SAR"}');
SELECT throws_ok($$SELECT public.change_bank_account_state((result->>'id')::uuid,'2000-01-01','delete') FROM bank_fixture$$,'P0001','BNK002: bank account changed; reload first','stale deletion rejected');
SELECT lives_ok($$SELECT public.change_bank_account_state((result->>'id')::uuid,(result->>'updated_at')::timestamptz,'delete') FROM bank_fixture$$,'unused account can be soft deleted');
RESET ROLE;
SELECT ok((SELECT deleted_at IS NOT NULL AND NOT is_active FROM public.bank_accounts WHERE id=(SELECT (result->>'id')::uuid FROM bank_fixture)),'deletion retains inactive record');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE entity_id=(SELECT (result->>'id')::uuid FROM bank_fixture) AND action='bank_account_deleted'),1,'deletion audited');
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.save_bank_account('{}')$$,'42501',NULL,'anonymous execution denied');
SELECT * FROM finish();
ROLLBACK;
